CREATE TABLE ssl_settings (
    id                 INT          NOT NULL DEFAULT 1,
    enabled            TINYINT(1)   NOT NULL DEFAULT 0,
    cert_type          VARCHAR(20)  NULL,
    domain             VARCHAR(500) NULL,
    keystore_path      VARCHAR(500) NULL,
    keystore_password  VARCHAR(200) NULL,
    https_port         INT          NOT NULL DEFAULT 3443,
    cert_subject       VARCHAR(500) NULL,
    cert_issuer        VARCHAR(500) NULL,
    cert_expiry        DATETIME     NULL,
    created_at         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);



